:root {
  --bg: #1a1a2e;
  --primary: #0f3460;
  --accent: #e94560;
  --text: #eaeaea;
  --text-dark: #16213e;
  --ground: #2d3561;
  --platform: #16a085;
  --goal: #ffd700;
  --radius: 8px;
  --font: system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

canvas {
  display: block;
  position: fixed;
  top: 0; left: 0;
  width: 100%;
  height: 100%;
}

/* HUD */
.hud {
  position: fixed;
  top: 12px;
  left: 12px;
  right: 12px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  z-index: 10;
  pointer-events: none;
}

.hud-score,
.hud-level {
  background: rgba(16,52,96,0.85);
  padding: 8px 14px;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 14px;
  border: 2px solid var(--accent);
  color: var(--text);
}

#score-value,
#level-value {
  color: var(--goal);
  font-weight: 700;
}

/* Screens */
.screen {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0,0,0,0.92);
  z-index: 20;
}

.screen-container,
.menu-container {
  padding: 24px;
  max-width: 90%;
  width: 100%;
  max-height: 90vh;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  text-align: center;
}

.menu-title {
  font-size: clamp(32px, 8vw, 56px);
  font-weight: 700;
  margin: 0 0 8px 0;
  color: var(--accent);
  letter-spacing: 2px;
}

.menu-subtitle {
  font-size: 17px;
  color: var(--text);
  margin: 0 0 32px 0;
  opacity: 0.9;
}

.screen-title {
  font-size: clamp(24px, 6vw, 36px);
  font-weight: 700;
  margin: 0 0 20px 0;
  color: var(--accent);
  text-align: center;
}

.screen-content {
  font-size: 15px;
  line-height: 1.7;
  color: var(--text);
  margin: 0 0 24px 0;
  text-align: left;
}

.screen-content p { margin: 10px 0; }
.screen-content strong { color: var(--goal); }

#gameover-message {
  font-size: 16px;
  color: var(--text);
}

/* Buttons */
.btn {
  display: block;
  width: 100%;
  max-width: 280px;
  margin: 12px auto;
  padding: 16px 24px;
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: opacity 0.15s;
}

.btn:active { opacity: 0.75; }

.btn-primary {
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
}

.btn-secondary {
  background: transparent;
  color: var(--text);
  border: 2px solid rgba(255,255,255,0.3);
}

/* Virtual Controls */
.controls {
  position: fixed;
  bottom: 20px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 20px;
  z-index: 15;
  pointer-events: none;
}

.control-btn {
  pointer-events: all;
  width: 72px;
  height: 72px;
  border-radius: 50%;
  border: 3px solid rgba(255,255,255,0.5);
  background: rgba(15,52,96,0.8);
  color: #fff;
  font-size: 22px;
  font-weight: 700;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.1s;
  user-select: none;
}

.control-btn:active,
.control-btn.pressed {
  background: rgba(233,69,96,0.8);
}

.control-jump {
  width: 88px;
  height: 88px;
  font-size: 14px;
  background: rgba(233,69,96,0.7);
  border-color: var(--accent);
}

// =============================================================================
// PLATFORMER GAME
// =============================================================================

const canvas = document.getElementById('game-canvas');
if (!canvas) { console.error('Canvas not found'); }
const ctx = canvas ? canvas.getContext('2d') : null;

let gameState = 'menu'; // 'menu' | 'playing' | 'gameover' | 'howtoplay'
let score = 0;
let currentLevel = 1;
const maxLevels = 3;
let jumpPressed = false; // edge-trigger for jump

// Player
let player = {
  x: 0, y: 0,
  width: 26, height: 34,
  velocityX: 0, velocityY: 0,
  isGrounded: false,
  jumpPower: -14,
  maxSpeed: 5,
  friction: 0.80,
  gravity: 0.55
};

// Input
let input = { left: false, right: false, jump: false };
let prevJump = false;

// World
let platforms = [];
let goal = null;
let gameWidth = window.innerWidth;
let gameHeight = window.innerHeight;

// Stars for background
let stars = [];

// =============================================================================
// CANVAS RESIZE
// =============================================================================
function resizeCanvas() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  gameWidth = canvas.width;
  gameHeight = canvas.height;
}
window.addEventListener('resize', () => { resizeCanvas(); if (gameState === 'playing') setupLevel(currentLevel); });
resizeCanvas();

// Generate stars once
function generateStars() {
  stars = [];
  for (let i = 0; i < 80; i++) {
    stars.push({
      x: Math.random() * gameWidth,
      y: Math.random() * gameHeight * 0.7,
      r: Math.random() * 1.5 + 0.3,
      a: Math.random() * 0.8 + 0.2
    });
  }
}
generateStars();

// =============================================================================
// SCREEN MANAGEMENT
// =============================================================================
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.style.display = 'none');
  if (id) {
    const el = document.getElementById(id);
    if (el) el.style.display = 'flex';
  }
}

function showHUD(visible) {
  const hud = document.getElementById('hud');
  const ctrl = document.getElementById('controls');
  if (hud) hud.style.display = visible ? 'flex' : 'none';
  if (ctrl) ctrl.style.display = visible ? 'flex' : 'none';
}

function updateHUD() {
  const sv = document.getElementById('score-value');
  const lv = document.getElementById('level-value');
  if (sv) sv.textContent = score;
  if (lv) lv.textContent = currentLevel;
}

// =============================================================================
// GAME STATE TRANSITIONS
// =============================================================================
function startGame() {
  score = 0;
  currentLevel = 1;
  gameState = 'playing';
  showScreen(null);
  showHUD(true);
  setupLevel(currentLevel);
}

function restartLevel() {
  gameState = 'playing';
  showScreen(null);
  showHUD(true);
  setupLevel(currentLevel);
}

function nextLevel() {
  currentLevel++;
  if (currentLevel > maxLevels) {
    // All levels done — show win
    gameState = 'gameover';
    const t = document.getElementById('gameover-title');
    const m = document.getElementById('gameover-message');
    if (t) t.textContent = '🏆 YOU WIN!';
    if (m) m.textContent = `All levels complete! Final Score: ${score}`;
    const nextBtn = document.getElementById('next-btn');
    if (nextBtn) nextBtn.style.display = 'none';
    showHUD(false);
    showScreen('gameover-screen');
    return;
  }
  gameState = 'playing';
  showScreen(null);
  showHUD(true);
  setupLevel(currentLevel);
}

function backToMenu() {
  gameState = 'menu';
  showHUD(false);
  showScreen('menu-screen');
  resetInput();
}

function showHowToPlay() {
  gameState = 'howtoplay';
  showScreen('how-screen');
}

function resetInput() {
  input.left = false;
  input.right = false;
  input.jump = false;
  prevJump = false;
  jumpPressed = false;
}

// =============================================================================
// LEVEL SETUP
// =============================================================================
function setupLevel(levelNum) {
  platforms = [];
  goal = null;
  resetInput();
  generateStars();

  const gw = gameWidth;
  const gh = gameHeight;
  const baseY = gh - 80;

  // Ground / starting platform always at left
  platforms.push({ x: 20, y: baseY, width: 130, height: 20, color: '#16a085' });

  if (levelNum === 1) {
    platforms.push({ x: 200, y: baseY - 100, width: 120, height: 20, color: '#16a085' });
    platforms.push({ x: 370, y: baseY - 180, width: 110, height: 20, color: '#16a085' });
    platforms.push({ x: 530, y: baseY - 140, width: 110, height: 20, color: '#1abc9c' });
    platforms.push({ x: 690, y: baseY - 220, width: 100, height: 20, color: '#1abc9c' });
    goal = { x: gw - 110, y: baseY - 280, width: 50, height: 50 };
  } else if (levelNum === 2) {
    platforms.push({ x: 190, y: baseY - 80,  width: 90, height: 20, color: '#16a085' });
    platforms.push({ x: 330, y: baseY - 170, width: 85, height: 20, color: '#16a085' });
    platforms.push({ x: 180, y: baseY - 260, width: 80, height: 20, color: '#1abc9c' });
    platforms.push({ x: 360, y: baseY - 330, width: 85, height: 20, color: '#1abc9c' });
    platforms.push({ x: 530, y: baseY - 250, width: 80, height: 20, color: '#27ae60' });
    platforms.push({ x: 680, y: baseY - 160, width: 95, height: 20, color: '#27ae60' });
    goal = { x: gw - 110, y: baseY - 340, width: 50, height: 50 };
  } else {
    platforms.push({ x: 160, y: baseY - 100, width: 75, height: 20, color: '#16a085' });
    platforms.push({ x: 290, y: baseY - 190, width: 70, height: 20, color: '#1abc9c' });
    platforms.push({ x: 420, y: baseY - 120, width: 70, height: 20, color: '#16a085' });
    platforms.push({ x: 220, y: baseY - 290, width: 70, height: 20, color: '#27ae60' });
    platforms.push({ x: 430, y: baseY - 360, width: 75, height: 20, color: '#1abc9c' });
    platforms.push({ x: 600, y: baseY - 270, width: 70, height: 20, color: '#27ae60' });
    platforms.push({ x: 710, y: baseY - 180, width: 80, height: 20, color: '#16a085' });
    goal = { x: gw - 110, y: baseY - 420, width: 50, height: 50 };
  }

  // Clamp goal to visible area
  if (goal) {
    goal.x = Math.min(goal.x, gw - 60);
    goal.y = Math.max(goal.y, 60);
    // Add a platform under goal if needed
    platforms.push({ x: goal.x - 10, y: goal.y + goal.height, width: goal.width + 20, height: 20, color: '#f39c12' });
  }

  // Init player
  player.x = 40;
  player.y = baseY - 60;
  player.velocityX = 0;
  player.velocityY = 0;
  player.isGrounded = false;

  updateHUD();
}

// =============================================================================
// UPDATE
// =============================================================================
function update(dt) {
  if (gameState !== 'playing') return;

  // Gravity
  player.velocityY += player.gravity;

  // Horizontal input
  if (input.left) {
    player.velocityX -= 1.2;
    if (player.velocityX < -player.maxSpeed) player.velocityX = -player.maxSpeed;
  } else if (input.right) {
    player.velocityX += 1.2;
    if (player.velocityX > player.maxSpeed) player.velocityX = player.maxSpeed;
  } else {
    player.velocityX *= player.friction;
    if (Math.abs(player.velocityX) < 0.1) player.velocityX = 0;
  }

  // Jump (edge trigger)
  const jumpEdge = input.jump && !prevJump;
  if (jumpEdge && player.isGrounded) {
    player.velocityY = player.jumpPower;
    player.isGrounded = false;
  }
  prevJump = input.jump;

  // Move X
  player.x += player.velocityX;

  // Screen boundary X
  if (player.x < 0) { player.x = 0; player.velocityX = 0; }
  if (player.x + player.width > gameWidth) { player.x = gameWidth - player.width; player.velocityX = 0; }

  // Move Y then check platform collisions
  player.y += player.velocityY;
  player.isGrounded = false;

  for (const p of platforms) {
    // Only collide from above (landing on top)
    if (
      player.velocityY >= 0 &&
      player.x + player.width > p.x + 4 &&
      player.x < p.x + p.width - 4 &&
      player.y + player.height >= p.y &&
      player.y + player.height <= p.y + p.height + Math.abs(player.velocityY) + 2
    ) {
      player.y = p.y - player.height;
      player.velocityY = 0;
      player.isGrounded = true;
    }
  }

  // Fell out of world
  if (player.y > gameHeight + 100) {
    endLevel(false);
    return;
  }

  // Check goal
  if (goal && rectsOverlap(player, goal)) {
    endLevel(true);
  }
}

function rectsOverlap(a, b) {
  return a.x < b.x + b.width &&
         a.x + a.width > b.x &&
         a.y < b.y + b.height &&
         a.y + a.height > b.y;
}

function endLevel(won) {
  gameState = 'gameover';
  const title = document.getElementById('gameover-title');
  const msg   = document.getElementById('gameover-message');
  const nextBtn = document.getElementById('next-btn');

  if (won) {
    score += currentLevel * 50;
    if (title) title.textContent = '🎉 LEVEL COMPLETE!';
    if (msg) msg.textContent = `Level ${currentLevel} done! Score: ${score}`;
    if (nextBtn) nextBtn.style.display = currentLevel < maxLevels ? 'block' : 'none';
  } else {
    if (title) title.textContent = '💀 YOU FELL!';
    if (msg) msg.textContent = 'Try again!';
    if (nextBtn) nextBtn.style.display = 'none';
  }

  showHUD(false);
  showScreen('gameover-screen');
}

// =============================================================================
// DRAW
// =============================================================================
function draw() {
  ctx.clearRect(0, 0, gameWidth, gameHeight);

  // Background gradient
  const bg = ctx.createLinearGradient(0, 0, 0, gameHeight);
  bg.addColorStop(0, '#070d1a');
  bg.addColorStop(1, '#0f2040');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, gameWidth, gameHeight);

  // Stars
  for (const s of stars) {
    ctx.globalAlpha = s.a;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // Ground line
  ctx.fillStyle = '#0d2137';
  ctx.fillRect(0, gameHeight - 60, gameWidth, 60);
  ctx.fillStyle = '#16a085';
  ctx.fillRect(0, gameHeight - 64, gameWidth, 4);

  // Platforms
  for (const p of platforms) {
    // Shadow
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(p.x + 4, p.y + 6, p.width, p.height);
    // Body
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x, p.y, p.width, p.height);
    // Top highlight
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    ctx.fillRect(p.x, p.y, p.width, 4);
  }

  // Goal (flag)
  if (goal) {
    const gx = goal.x, gy = goal.y, gw = goal.width, gh = goal.height;
    // Glow
    ctx.save();
    ctx.shadowColor = '#ffd700';
    ctx.shadowBlur = 18;
    ctx.fillStyle = '#ffd700';
    ctx.fillRect(gx, gy, gw, gh);
    ctx.restore();
    // Shine
    ctx.fillStyle = 'rgba(255,255,255,0.35)';
    ctx.fillRect(gx + 4, gy + 4, gw - 8, gh * 0.35);
    // Star symbol
    ctx.fillStyle = '#fff';
    ctx.font = `bold ${Math.min(gw, gh) * 0.55}px sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('★', gx + gw / 2, gy + gh / 2);
  }

  // Player
  const px = player.x, py = player.y, pw = player.width, ph = player.height;
  // Body
  ctx.fillStyle = '#e94560';
  ctx.fillRect(px, py, pw, ph);
  // Head highlight
  ctx.fillStyle = 'rgba(255,255,255,0.2)';
  ctx.fillRect(px, py, pw, ph * 0.35);
  // Eyes
  ctx.fillStyle = '#fff';
  ctx.fillRect(px + 5, py + 8, 5, 5);
  ctx.fillRect(px + pw - 10, py + 8, 5, 5);
  // Pupils
  ctx.fillStyle = '#222';
  ctx.fillRect(px + 7, py + 10, 2, 2);
  ctx.fillRect(px + pw - 8, py + 10, 2, 2);
  // Legs (simple)
  ctx.fillStyle = '#c0392b';
  if (!player.isGrounded) {
    // airborne pose
    ctx.fillRect(px + 2, py + ph - 10, 8, 10);
    ctx.fillRect(px + pw - 10, py + ph - 10, 8, 10);
  } else {
    ctx.fillRect(px + 2, py + ph - 8, 8, 8);
    ctx.fillRect(px + pw - 10, py + ph - 8, 8, 8);
  }

  // HUD score/level already in DOM — no need to redraw on canvas
}

// =============================================================================
// GAME LOOP (RAF)
// =============================================================================
let lastTime = 0;
function gameLoop(ts) {
  const dt = Math.min((ts - lastTime) / 1000, 0.05);
  lastTime = ts;

  if (gameState === 'playing') {
    update(dt);
    draw();
  } else if (gameState === 'menu' || gameState === 'howtoplay') {
    // Draw idle background
    drawMenuBackground(ts);
  }

  requestAnimationFrame(gameLoop);
}
requestAnimationFrame(gameLoop);

function drawMenuBackground(ts) {
  ctx.clearRect(0, 0, gameWidth, gameHeight);
  const bg = ctx.createLinearGradient(0, 0, 0, gameHeight);
  bg.addColorStop(0, '#070d1a');
  bg.addColorStop(1, '#0f2040');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, gameWidth, gameHeight);
  // Twinkle stars
  for (const s of stars) {
    ctx.globalAlpha = s.a * (0.6 + 0.4 * Math.sin(ts * 0.001 + s.x));
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

// =============================================================================
// INPUT BINDING
// =============================================================================

// Keyboard
document.addEventListener('keydown', e => {
  if (e.key === 'ArrowLeft'  || e.key === 'a') input.left  = true;
  if (e.key === 'ArrowRight' || e.key === 'd') input.right = true;
  if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'w') input.jump = true;
  e.preventDefault();
});
document.addEventListener('keyup', e => {
  if (e.key === 'ArrowLeft'  || e.key === 'a') input.left  = false;
  if (e.key === 'ArrowRight' || e.key === 'd') input.right = false;
  if (e.key === ' ' || e.key === 'ArrowUp' || e.key === 'w') input.jump = false;
});

// Virtual buttons
function bindBtn(id, inputKey) {
  const el = document.getElementById(id);
  if (!el) return;
  const down = e => { e.preventDefault(); input[inputKey] = true;  el.classList.add('pressed'); };
  const up   = e => { e.preventDefault(); input[inputKey] = false; el.classList.remove('pressed'); };
  el.addEventListener('pointerdown',  down);
  el.addEventListener('pointerup',    up);
  el.addEventListener('pointerout',   up);
  el.addEventListener('pointercancel',up);
}
bindBtn('left-btn',  'left');
bindBtn('right-btn', 'right');
bindBtn('jump-btn',  'jump');

// Canvas tap (fallback/extra)
canvas.addEventListener('pointerdown', e => {
  if (gameState !== 'playing') return;
  const r = canvas.getBoundingClientRect();
  const tx = e.clientX - r.left;
  // Tap left half = move left, right half = move right; upper third = jump
  // (virtual buttons are primary; this is extra)
});

// Menu / screen buttons
document.getElementById('start-btn')  ?.addEventListener('click', startGame);
document.getElementById('how-btn')    ?.addEventListener('click', showHowToPlay);
document.getElementById('back-btn')   ?.addEventListener('click', backToMenu);
document.getElementById('restart-btn')?.addEventListener('click', restartLevel);
document.getElementById('next-btn')   ?.addEventListener('click', nextLevel);
document.getElementById('menu-btn')   ?.addEventListener('click', backToMenu);

// Show menu at startup
showScreen('menu-screen');
showHUD(false);
